import {
  Alert,
  AlertDescription,
  AlertTitle,
  Badge,
  Button,
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
  Checkbox,
  Input,
  Label,
  Progress,
  RadioGroup,
  RadioGroupItem,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Separator,
  Slider,
  Textarea,
} from "@databricks/appkit-ui/react";
import { Check, ChevronLeft, ChevronRight, Send, TriangleAlert } from "lucide-react";
import { useState } from "react";

import {
  benefitPlans,
  countries,
  departments,
  emptyDraft,
  employmentTypes,
  laptops,
  managers,
  monitors,
  officeLocations,
  peripherals,
  retirementMatchCapPercent,
  sampleDraft,
  steps,
} from "../mock";
import type {
  BenefitPlan,
  EquipmentOption,
  OnboardingDraft,
  ValidationErrors,
} from "../mock";

const money = (n: number) => `$${n.toLocaleString()}`;

function validate(stepId: string, d: OnboardingDraft): ValidationErrors {
  const e: ValidationErrors = {};
  if (stepId === "personal") {
    const p = d.personal;
    if (!p.firstName.trim()) e.firstName = "First name is required";
    if (!p.lastName.trim()) e.lastName = "Last name is required";
    if (!/^\S+@\S+\.\S+$/.test(p.email)) e.email = "Enter a valid email";
    if (!p.phone.trim()) e.phone = "Phone is required";
    if (!p.dateOfBirth) e.dateOfBirth = "Date of birth is required";
    if (!p.address.trim()) e.address = "Address is required";
    if (!p.city.trim()) e.city = "City is required";
    if (!p.country) e.country = "Select a country";
    if (!p.postalCode.trim()) e.postalCode = "Postal code is required";
    if (!p.emergencyContactName.trim())
      e.emergencyContactName = "Emergency contact is required";
    if (!p.emergencyContactPhone.trim())
      e.emergencyContactPhone = "Emergency phone is required";
  }
  if (stepId === "role") {
    const r = d.role;
    if (!r.jobTitle.trim()) e.jobTitle = "Job title is required";
    if (!r.departmentId) e.departmentId = "Select a department";
    if (!r.team) e.team = "Select a team";
    if (!r.managerId) e.managerId = "Select a manager";
    if (!r.employmentType) e.employmentType = "Select employment type";
    if (!r.startDate) e.startDate = "Start date is required";
    if (!r.location) e.location = "Select an office location";
  }
  if (stepId === "equipment") {
    const q = d.equipment;
    if (!q.laptopId) e.laptopId = "Choose a laptop";
    if (!q.monitorId) e.monitorId = "Choose a monitor";
    if (!q.shippingAddress.trim()) e.shippingAddress = "Shipping address is required";
  }
  if (stepId === "benefits") {
    const b = d.benefits;
    if (!b.healthPlanId) e.healthPlanId = "Select a health plan";
    if (!b.dentalPlanId) e.dentalPlanId = "Select a dental option";
    if (!b.visionPlanId) e.visionPlanId = "Select a vision option";
  }
  return e;
}

function FieldBox({
  label,
  id,
  error,
  children,
}: {
  label: string;
  id: string;
  error?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="space-y-1.5">
      <Label htmlFor={id}>{label}</Label>
      {children}
      {error && <p className="text-xs text-destructive">{error}</p>}
    </div>
  );
}

export default function Onboarding() {
  const [draft, setDraft] = useState<OnboardingDraft>(emptyDraft);
  const [stepIdx, setStepIdx] = useState(0);
  const [errors, setErrors] = useState<ValidationErrors>({});
  const [done, setDone] = useState<number[]>([]);
  const [submitted, setSubmitted] = useState(false);

  const step = steps[stepIdx];
  const isLast = stepIdx === steps.length - 1;

  const setP = (k: keyof OnboardingDraft["personal"], v: string) =>
    setDraft((d) => ({ ...d, personal: { ...d.personal, [k]: v } }));
  const setR = (k: keyof OnboardingDraft["role"], v: string) =>
    setDraft((d) => ({ ...d, role: { ...d.role, [k]: v } }));
  const setE = <K extends keyof OnboardingDraft["equipment"]>(
    k: K,
    v: OnboardingDraft["equipment"][K],
  ) => setDraft((d) => ({ ...d, equipment: { ...d.equipment, [k]: v } }));
  const setB = <K extends keyof OnboardingDraft["benefits"]>(
    k: K,
    v: OnboardingDraft["benefits"][K],
  ) => setDraft((d) => ({ ...d, benefits: { ...d.benefits, [k]: v } }));

  const next = () => {
    const e = validate(step.id, draft);
    setErrors(e);
    if (Object.keys(e).length) return;
    setDone((d) => (d.includes(stepIdx) ? d : [...d, stepIdx]));
    setStepIdx(stepIdx + 1);
  };
  const back = () => {
    setErrors({});
    setStepIdx(stepIdx - 1);
  };
  const submit = () => {
    for (let i = 0; i < steps.length - 1; i++) {
      const e = validate(steps[i].id, draft);
      if (Object.keys(e).length) {
        setErrors(e);
        setStepIdx(i);
        return;
      }
    }
    setSubmitted(true);
  };

  const p = draft.personal;
  const r = draft.role;
  const dept = departments.find((x) => x.id === r.departmentId);
  const manager = managers.find((m) => m.id === r.managerId);
  const teams = dept?.teams ?? [];
  const availableManagers = managers.filter(
    (m) => !r.departmentId || m.departmentId === r.departmentId,
  );

  const findOpt = (list: EquipmentOption[], id: string) =>
    list.find((o) => o.id === id);
  const equipmentTotal =
    (findOpt(laptops, draft.equipment.laptopId)?.price ?? 0) +
    (findOpt(monitors, draft.equipment.monitorId)?.price ?? 0) +
    draft.equipment.peripheralIds.reduce(
      (s, id) => s + (findOpt(peripherals, id)?.price ?? 0),
      0,
    );

  const plansBy = (c: BenefitPlan["category"]) =>
    benefitPlans.filter((b) => b.category === c);
  const selectedPlanIds = [
    draft.benefits.healthPlanId,
    draft.benefits.dentalPlanId,
    draft.benefits.visionPlanId,
    ...draft.benefits.wellnessIds,
  ];
  const selectedPlans = benefitPlans.filter((b) => selectedPlanIds.includes(b.id));
  const monthlyEmployee = selectedPlans.reduce(
    (s, b) => s + Math.max(0, b.monthlyCost - b.employerContribution),
    0,
  );

  const text = (
    id: string,
    label: string,
    value: string,
    onChange: (v: string) => void,
    opts: { type?: string; placeholder?: string } = {},
  ) => (
    <FieldBox label={label} id={id} error={errors[id]}>
      <Input
        id={id}
        type={opts.type}
        placeholder={opts.placeholder}
        value={value}
        onChange={(e) => onChange(e.target.value)}
      />
    </FieldBox>
  );

  const planGroup = (
    title: string,
    cat: BenefitPlan["category"],
    key: "healthPlanId" | "dentalPlanId" | "visionPlanId",
  ) => (
    <div className="space-y-2">
      <h3 className="text-sm font-medium">{title}</h3>
      <RadioGroup
        value={draft.benefits[key]}
        onValueChange={(v) => setB(key, v)}
      >
        {plansBy(cat).map((b) => (
          <label
            key={b.id}
            htmlFor={`${key}-${b.id}`}
            className="flex cursor-pointer items-start gap-3 rounded-md border p-3"
          >
            <RadioGroupItem value={b.id} id={`${key}-${b.id}`} />
            <div className="flex-1">
              <div className="text-sm font-medium">{b.name}</div>
              <div className="text-xs text-muted-foreground">{b.description}</div>
            </div>
            <div className="text-right text-xs tabular-nums">
              <div>{money(b.monthlyCost)}/mo</div>
              <div className="text-muted-foreground">
                Employer {money(b.employerContribution)}
              </div>
            </div>
          </label>
        ))}
      </RadioGroup>
      {errors[key] && <p className="text-xs text-destructive">{errors[key]}</p>}
    </div>
  );

  const reviewRow = (k: string, v: string) => (
    <div className="flex justify-between gap-4 py-1.5 text-sm">
      <span className="text-muted-foreground">{k}</span>
      <span className="text-right font-medium">{v || "—"}</span>
    </div>
  );

  if (submitted) {
    return (
      <div className="mx-auto max-w-2xl p-6">
        <Card>
          <CardHeader>
            <div className="mb-2 flex size-10 items-center justify-center rounded-full bg-success/15 text-success">
              <Check className="size-5" />
            </div>
            <CardTitle>Onboarding submitted</CardTitle>
            <CardDescription>
              Thanks, {p.preferredName || p.firstName}. Your manager and IT have been notified.
            </CardDescription>
          </CardHeader>
          <CardFooter>
            <Button
              variant="outline"
              onClick={() => {
                setDraft(emptyDraft);
                setDone([]);
                setStepIdx(0);
                setSubmitted(false);
              }}
            >
              Start over
            </Button>
          </CardFooter>
        </Card>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-5xl space-y-6 p-6">
      <header className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">New employee onboarding</h1>
          <p className="text-sm text-muted-foreground">
            Step {stepIdx + 1} of {steps.length} · {step.label}
          </p>
        </div>
        <Button
          variant="ghost"
          size="sm"
          onClick={() => {
            setDraft(sampleDraft);
            setErrors({});
          }}
        >
          Fill sample data
        </Button>
      </header>

      <Progress value={((stepIdx + (done.includes(stepIdx) ? 1 : 0)) / steps.length) * 100} />

      <div className="grid gap-6 md:grid-cols-[220px_1fr]">
        <nav className="space-y-1">
          {steps.map((s, i) => {
            const complete = done.includes(i);
            const current = i === stepIdx;
            return (
              <button
                key={s.id}
                type="button"
                disabled={!complete && !current}
                onClick={() => {
                  setErrors({});
                  setStepIdx(i);
                }}
                className={`flex w-full items-start gap-3 rounded-md border p-3 text-left ${
                  current ? "border-primary bg-muted" : "border-transparent"
                } disabled:opacity-60`}
              >
                <span
                  className={`mt-0.5 flex size-6 shrink-0 items-center justify-center rounded-full text-xs ${
                    complete
                      ? "bg-success text-primary-foreground"
                      : current
                        ? "bg-primary text-primary-foreground"
                        : "bg-secondary text-muted-foreground"
                  }`}
                >
                  {complete ? <Check className="size-3.5" /> : i + 1}
                </span>
                <span>
                  <span className="block text-sm font-medium">{s.label}</span>
                  <span className="block text-xs text-muted-foreground">{s.description}</span>
                </span>
              </button>
            );
          })}
        </nav>

        <Card>
          <CardHeader>
            <CardTitle>{step.label}</CardTitle>
            <CardDescription>{step.description}</CardDescription>
          </CardHeader>
          <CardContent className="space-y-5">
            {Object.keys(errors).length > 0 && (
              <Alert variant="destructive">
                <TriangleAlert />
                <AlertTitle>Please fix {Object.keys(errors).length} issue(s)</AlertTitle>
                <AlertDescription>Complete the highlighted fields to continue.</AlertDescription>
              </Alert>
            )}

            {step.id === "personal" && (
              <>
                <div className="grid gap-4 sm:grid-cols-3">
                  {text("firstName", "First name", p.firstName, (v) => setP("firstName", v))}
                  {text("lastName", "Last name", p.lastName, (v) => setP("lastName", v))}
                  {text("preferredName", "Preferred name", p.preferredName, (v) => setP("preferredName", v))}
                </div>
                <div className="grid gap-4 sm:grid-cols-3">
                  {text("email", "Personal email", p.email, (v) => setP("email", v), { type: "email" })}
                  {text("phone", "Phone", p.phone, (v) => setP("phone", v))}
                  {text("dateOfBirth", "Date of birth", p.dateOfBirth, (v) => setP("dateOfBirth", v), { type: "date" })}
                </div>
                <Separator />
                {text("address", "Street address", p.address, (v) => setP("address", v))}
                <div className="grid gap-4 sm:grid-cols-3">
                  {text("city", "City", p.city, (v) => setP("city", v))}
                  <FieldBox label="Country" id="country" error={errors.country}>
                    <Select value={p.country} onValueChange={(v) => setP("country", v)}>
                      <SelectTrigger id="country">
                        <SelectValue placeholder="Select" />
                      </SelectTrigger>
                      <SelectContent>
                        {countries.map((c) => (
                          <SelectItem key={c} value={c}>{c}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </FieldBox>
                  {text("postalCode", "Postal code", p.postalCode, (v) => setP("postalCode", v))}
                </div>
                <Separator />
                <div className="grid gap-4 sm:grid-cols-2">
                  {text("emergencyContactName", "Emergency contact name", p.emergencyContactName, (v) => setP("emergencyContactName", v))}
                  {text("emergencyContactPhone", "Emergency contact phone", p.emergencyContactPhone, (v) => setP("emergencyContactPhone", v))}
                </div>
              </>
            )}

            {step.id === "role" && (
              <>
                <div className="grid gap-4 sm:grid-cols-2">
                  {text("jobTitle", "Job title", r.jobTitle, (v) => setR("jobTitle", v))}
                  {text("startDate", "Start date", r.startDate, (v) => setR("startDate", v), { type: "date" })}
                  <FieldBox label="Department" id="departmentId" error={errors.departmentId}>
                    <Select
                      value={r.departmentId}
                      onValueChange={(v) =>
                        setDraft((d) => ({
                          ...d,
                          role: { ...d.role, departmentId: v, team: "", managerId: "" },
                        }))
                      }
                    >
                      <SelectTrigger id="departmentId"><SelectValue placeholder="Select" /></SelectTrigger>
                      <SelectContent>
                        {departments.map((x) => (
                          <SelectItem key={x.id} value={x.id}>{x.name}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </FieldBox>
                  <FieldBox label="Team" id="team" error={errors.team}>
                    <Select value={r.team} onValueChange={(v) => setR("team", v)}>
                      <SelectTrigger id="team"><SelectValue placeholder={dept ? "Select" : "Pick a department first"} /></SelectTrigger>
                      <SelectContent>
                        {teams.map((t) => (
                          <SelectItem key={t} value={t}>{t}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </FieldBox>
                  <FieldBox label="Manager" id="managerId" error={errors.managerId}>
                    <Select value={r.managerId} onValueChange={(v) => setR("managerId", v)}>
                      <SelectTrigger id="managerId"><SelectValue placeholder="Select" /></SelectTrigger>
                      <SelectContent>
                        {availableManagers.map((m) => (
                          <SelectItem key={m.id} value={m.id}>{m.name} · {m.title}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </FieldBox>
                  <FieldBox label="Office location" id="location" error={errors.location}>
                    <Select value={r.location} onValueChange={(v) => setR("location", v)}>
                      <SelectTrigger id="location"><SelectValue placeholder="Select" /></SelectTrigger>
                      <SelectContent>
                        {officeLocations.map((l) => (
                          <SelectItem key={l} value={l}>{l}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </FieldBox>
                </div>
                <FieldBox label="Employment type" id="employmentType" error={errors.employmentType}>
                  <RadioGroup
                    value={r.employmentType}
                    onValueChange={(v) => setR("employmentType", v)}
                    className="flex flex-wrap gap-4"
                  >
                    {employmentTypes.map((t) => (
                      <div key={t.id} className="flex items-center gap-2">
                        <RadioGroupItem value={t.id} id={`et-${t.id}`} />
                        <Label htmlFor={`et-${t.id}`}>{t.label}</Label>
                      </div>
                    ))}
                  </RadioGroup>
                </FieldBox>
              </>
            )}

            {step.id === "equipment" && (
              <>
                {(
                  [
                    ["Laptop", laptops, "laptopId"],
                    ["Monitor", monitors, "monitorId"],
                  ] as const
                ).map(([title, list, key]) => (
                  <div key={key} className="space-y-2">
                    <h3 className="text-sm font-medium">{title}</h3>
                    <RadioGroup
                      value={draft.equipment[key]}
                      onValueChange={(v) => setE(key, v)}
                    >
                      {list.map((o) => (
                        <label
                          key={o.id}
                          htmlFor={`${key}-${o.id}`}
                          className="flex cursor-pointer items-center gap-3 rounded-md border p-3"
                        >
                          <RadioGroupItem value={o.id} id={`${key}-${o.id}`} />
                          <div className="flex-1">
                            <div className="text-sm font-medium">{o.name}</div>
                            <div className="text-xs text-muted-foreground">{o.description}</div>
                          </div>
                          <span className="text-sm tabular-nums">{money(o.price)}</span>
                        </label>
                      ))}
                    </RadioGroup>
                    {errors[key] && <p className="text-xs text-destructive">{errors[key]}</p>}
                  </div>
                ))}
                <div className="space-y-2">
                  <h3 className="text-sm font-medium">Peripherals (optional)</h3>
                  <div className="grid gap-2 sm:grid-cols-2">
                    {peripherals.map((o) => (
                      <label
                        key={o.id}
                        htmlFor={`per-${o.id}`}
                        className="flex cursor-pointer items-center gap-3 rounded-md border p-3"
                      >
                        <Checkbox
                          id={`per-${o.id}`}
                          checked={draft.equipment.peripheralIds.includes(o.id)}
                          onCheckedChange={(c) =>
                            setE(
                              "peripheralIds",
                              c === true
                                ? [...draft.equipment.peripheralIds, o.id]
                                : draft.equipment.peripheralIds.filter((x) => x !== o.id),
                            )
                          }
                        />
                        <span className="flex-1 text-sm">{o.name}</span>
                        <span className="text-sm tabular-nums text-muted-foreground">{money(o.price)}</span>
                      </label>
                    ))}
                  </div>
                </div>
                <FieldBox label="Shipping address" id="shippingAddress" error={errors.shippingAddress}>
                  <Input
                    id="shippingAddress"
                    value={draft.equipment.shippingAddress}
                    onChange={(e) => setE("shippingAddress", e.target.value)}
                  />
                </FieldBox>
                <FieldBox label="Notes" id="notes">
                  <Textarea
                    rows={3}
                    value={draft.equipment.notes}
                    onChange={(e) => setE("notes", e.target.value)}
                  />
                </FieldBox>
                <div className="flex justify-between rounded-md bg-muted p-3 text-sm">
                  <span className="text-muted-foreground">Equipment total</span>
                  <span className="font-medium tabular-nums">{money(equipmentTotal)}</span>
                </div>
              </>
            )}

            {step.id === "benefits" && (
              <>
                {planGroup("Health", "health", "healthPlanId")}
                {planGroup("Dental", "dental", "dentalPlanId")}
                {planGroup("Vision", "vision", "visionPlanId")}
                <Separator />
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <h3 className="text-sm font-medium">401(k) contribution</h3>
                    <Badge variant="secondary">{draft.benefits.retirementPercent}%</Badge>
                  </div>
                  <Slider
                    min={0}
                    max={25}
                    step={1}
                    value={[draft.benefits.retirementPercent]}
                    onValueChange={(v) => setB("retirementPercent", v[0] ?? 0)}
                  />
                  <p className="text-xs text-muted-foreground">
                    Employer matches up to {retirementMatchCapPercent}%.
                  </p>
                </div>
                <div className="space-y-2">
                  <h3 className="text-sm font-medium">Wellness (optional)</h3>
                  {plansBy("wellness").map((b) => (
                    <label
                      key={b.id}
                      htmlFor={`w-${b.id}`}
                      className="flex cursor-pointer items-center gap-3 rounded-md border p-3"
                    >
                      <Checkbox
                        id={`w-${b.id}`}
                        checked={draft.benefits.wellnessIds.includes(b.id)}
                        onCheckedChange={(c) =>
                          setB(
                            "wellnessIds",
                            c === true
                              ? [...draft.benefits.wellnessIds, b.id]
                              : draft.benefits.wellnessIds.filter((x) => x !== b.id),
                          )
                        }
                      />
                      <div className="flex-1">
                        <div className="text-sm font-medium">{b.name}</div>
                        <div className="text-xs text-muted-foreground">{b.description}</div>
                      </div>
                      <span className="text-sm tabular-nums">{money(b.monthlyCost)}/mo</span>
                    </label>
                  ))}
                </div>
              </>
            )}

            {step.id === "review" && (
              <div className="grid gap-6 md:grid-cols-2">
                <div>
                  <h3 className="mb-1 text-sm font-semibold">Personal</h3>
                  {reviewRow("Name", `${p.firstName} ${p.lastName}`)}
                  {reviewRow("Preferred", p.preferredName)}
                  {reviewRow("Email", p.email)}
                  {reviewRow("Phone", p.phone)}
                  {reviewRow("Date of birth", p.dateOfBirth)}
                  {reviewRow("Address", `${p.address}, ${p.city} ${p.postalCode}, ${p.country}`)}
                  {reviewRow("Emergency", `${p.emergencyContactName} · ${p.emergencyContactPhone}`)}
                </div>
                <div>
                  <h3 className="mb-1 text-sm font-semibold">Role</h3>
                  {reviewRow("Title", r.jobTitle)}
                  {reviewRow("Department", dept?.name ?? "")}
                  {reviewRow("Team", r.team)}
                  {reviewRow("Manager", manager?.name ?? "")}
                  {reviewRow("Type", employmentTypes.find((t) => t.id === r.employmentType)?.label ?? "")}
                  {reviewRow("Start date", r.startDate)}
                  {reviewRow("Location", r.location)}
                </div>
                <div>
                  <h3 className="mb-1 text-sm font-semibold">Equipment</h3>
                  {reviewRow("Laptop", findOpt(laptops, draft.equipment.laptopId)?.name ?? "")}
                  {reviewRow("Monitor", findOpt(monitors, draft.equipment.monitorId)?.name ?? "")}
                  {reviewRow(
                    "Peripherals",
                    draft.equipment.peripheralIds
                      .map((id) => findOpt(peripherals, id)?.name)
                      .filter(Boolean)
                      .join(", "),
                  )}
                  {reviewRow("Ship to", draft.equipment.shippingAddress)}
                  {reviewRow("Total", money(equipmentTotal))}
                </div>
                <div>
                  <h3 className="mb-1 text-sm font-semibold">Benefits</h3>
                  {selectedPlans.map((b) => reviewRow(b.name, `${money(b.monthlyCost)}/mo`))}
                  {reviewRow("401(k)", `${draft.benefits.retirementPercent}%`)}
                  {reviewRow("Your monthly cost", money(monthlyEmployee))}
                </div>
              </div>
            )}
          </CardContent>
          <CardFooter className="flex justify-between">
            <Button variant="outline" onClick={back} disabled={stepIdx === 0}>
              <ChevronLeft /> Back
            </Button>
            {isLast ? (
              <Button onClick={submit}>
                <Send /> Submit
              </Button>
            ) : (
              <Button onClick={next}>
                Continue <ChevronRight />
              </Button>
            )}
          </CardFooter>
        </Card>
      </div>
    </div>
  );
}

form-b.final:
import {
  Alert,
  AlertDescription,
  AlertTitle,
  Badge,
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  Checkbox,
  Input,
  Label,
  Progress,
  RadioGroup,
  RadioGroupItem,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Separator,
  Slider,
  Switch,
  Textarea,
} from "@databricks/appkit-ui/react";
import {
  ArrowLeft,
  ArrowRight,
  Check,
  CheckCircle2,
  PartyPopper,
} from "lucide-react";
import { useState } from "react";

import {
  benefitPlans,
  countries,
  departments,
  emptyDraft,
  employmentTypes,
  laptops,
  managers,
  monitors,
  officeLocations,
  peripherals,
  retirementMatchCapPercent,
  steps,
} from "../mock";
import type { OnboardingDraft, ValidationErrors } from "../mock";

const money = (n: number) => `$${n.toLocaleString()}`;

function FieldBox({
  label,
  id,
  error,
  children,
}: {
  label: string;
  id?: string;
  error?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="space-y-2">
      <Label htmlFor={id}>{label}</Label>
      {children}
      {error && <p className="text-xs text-destructive">{error}</p>}
    </div>
  );
}

export default function Onboarding() {
  const [draft, setDraft] = useState<OnboardingDraft>(emptyDraft);
  const [idx, setIdx] = useState(0);
  const [errors, setErrors] = useState<ValidationErrors>({});
  const [done, setDone] = useState(false);

  const step = steps[idx];
  const p = draft.personal;
  const r = draft.role;
  const e = draft.equipment;
  const b = draft.benefits;

  const setP = (k: keyof typeof p, v: string) =>
    setDraft({ ...draft, personal: { ...p, [k]: v } });
  const setR = (k: keyof typeof r, v: string) =>
    setDraft({ ...draft, role: { ...r, [k]: v } });
  const setE = (patch: Partial<typeof e>) =>
    setDraft({ ...draft, equipment: { ...e, ...patch } });
  const setB = (patch: Partial<typeof b>) =>
    setDraft({ ...draft, benefits: { ...b, ...patch } });

  const validate = (): ValidationErrors => {
    const er: ValidationErrors = {};
    if (step.id === "personal") {
      if (!p.firstName.trim()) er.firstName = "First name is required";
      if (!p.lastName.trim()) er.lastName = "Last name is required";
      if (!/^\S+@\S+\.\S+$/.test(p.email)) er.email = "Enter a valid email";
      if (!p.dateOfBirth) er.dateOfBirth = "Date of birth is required";
      if (!p.country) er.country = "Select a country";
      if (!p.emergencyContactName.trim())
        er.emergencyContactName = "Emergency contact is required";
    } else if (step.id === "role") {
      if (!r.jobTitle.trim()) er.jobTitle = "Job title is required";
      if (!r.departmentId) er.departmentId = "Select a department";
      if (!r.team) er.team = "Select a team";
      if (!r.managerId) er.managerId = "Select a manager";
      if (!r.employmentType) er.employmentType = "Select an employment type";
      if (!r.startDate) er.startDate = "Start date is required";
      if (!r.location) er.location = "Select a location";
    } else if (step.id === "equipment") {
      if (!e.laptopId) er.laptopId = "Choose a laptop";
      if (!e.monitorId) er.monitorId = "Choose a monitor option";
      if (!e.shippingAddress.trim())
        er.shippingAddress = "Shipping address is required";
    } else if (step.id === "benefits") {
      if (!b.healthPlanId) er.healthPlanId = "Choose a health plan";
    }
    return er;
  };

  const next = () => {
    const er = validate();
    setErrors(er);
    if (Object.keys(er).length) return;
    if (step.id === "review") setDone(true);
    else setIdx(idx + 1);
  };
  const back = () => {
    setErrors({});
    setIdx(Math.max(0, idx - 1));
  };

  const dept = departments.find((d) => d.id === r.departmentId);
  const teams = dept?.teams ?? [];
  const deptManagers = managers.filter((m) => m.departmentId === r.departmentId);
  const find = <T extends { id: string }>(list: T[], id: string) =>
    list.find((x) => x.id === id);
  const plansBy = (c: string) => benefitPlans.filter((x) => x.category === c);

  const equipCost = [
    find(laptops, e.laptopId)?.price ?? 0,
    find(monitors, e.monitorId)?.price ?? 0,
    ...e.peripheralIds.map((id) => find(peripherals, id)?.price ?? 0),
  ].reduce((a, c) => a + c, 0);
  const benefitCost = [b.healthPlanId, b.dentalPlanId, b.visionPlanId, ...b.wellnessIds]
    .map((id) => find(benefitPlans, id))
    .reduce((a, pl) => a + (pl ? pl.monthlyCost - pl.employerContribution : 0), 0);

  if (done) {
    return (
      <div className="mx-auto flex min-h-screen max-w-2xl flex-col items-center justify-center gap-6 p-10 text-center">
        <div className="rounded-full bg-success/15 p-6">
          <PartyPopper className="size-12 text-success" />
        </div>
        <h1 className="text-4xl font-semibold tracking-tight">
          Welcome aboard, {p.preferredName || p.firstName}!
        </h1>
        <p className="text-muted-foreground">
          Your onboarding is submitted. We'll email {p.email} with next steps
          before your start date.
        </p>
        <Button
          variant="outline"
          onClick={() => {
            setDraft(emptyDraft);
            setIdx(0);
            setDone(false);
          }}
        >
          Start over
        </Button>
      </div>
    );
  }

  const optionList = (
    items: typeof laptops,
    value: string,
    onChange: (v: string) => void,
    err?: string,
  ) => (
    <div className="space-y-2">
      <RadioGroup value={value} onValueChange={onChange} className="grid gap-3 sm:grid-cols-2">
        {items.map((o) => (
          <label
            key={o.id}
            htmlFor={`o-${o.id}`}
            className={`flex cursor-pointer items-start gap-3 rounded-lg border p-4 ${
              value === o.id ? "border-primary bg-primary/5" : "border-border"
            }`}
          >
            <RadioGroupItem value={o.id} id={`o-${o.id}`} />
            <div className="flex-1">
              <div className="font-medium">{o.name}</div>
              <div className="text-xs text-muted-foreground">{o.description}</div>
            </div>
            <span className="text-sm tabular-nums">{money(o.price)}</span>
          </label>
        ))}
      </RadioGroup>
      {err && <p className="text-xs text-destructive">{err}</p>}
    </div>
  );

  const planPicker = (cat: string, label: string, value: string, key: "healthPlanId" | "dentalPlanId" | "visionPlanId", err?: string) => (
    <div className="space-y-3">
      <h3 className="font-medium">{label}</h3>
      <RadioGroup value={value} onValueChange={(v) => setB({ [key]: v })} className="grid gap-3 sm:grid-cols-2">
        {plansBy(cat).map((pl) => (
          <label
            key={pl.id}
            htmlFor={`pl-${pl.id}`}
            className={`flex cursor-pointer items-start gap-3 rounded-lg border p-4 ${
              value === pl.id ? "border-primary bg-primary/5" : "border-border"
            }`}
          >
            <RadioGroupItem value={pl.id} id={`pl-${pl.id}`} />
            <div className="flex-1">
              <div className="font-medium">{pl.name}</div>
              <div className="text-xs text-muted-foreground">{pl.description}</div>
              <div className="mt-1 text-xs">
                You pay {money(pl.monthlyCost - pl.employerContribution)}/mo
              </div>
            </div>
          </label>
        ))}
      </RadioGroup>
      {err && <p className="text-xs text-destructive">{err}</p>}
    </div>
  );

  const row = (k: string, v: string) => (
    <div className="flex justify-between gap-4 py-1.5 text-sm">
      <span className="text-muted-foreground">{k}</span>
      <span className="text-right font-medium">{v || "—"}</span>
    </div>
  );

  return (
    <div className="mx-auto max-w-4xl space-y-10 px-6 py-12">
      <section className="space-y-6">
        <Badge variant="secondary">
          Step {idx + 1} of {steps.length}
        </Badge>
        <h1 className="text-5xl font-semibold tracking-tight">{step.label}</h1>
        <p className="max-w-xl text-lg text-muted-foreground">
          {step.description}
        </p>
        <Progress value={((idx + 1) / steps.length) * 100} />
        <ol className="flex flex-wrap gap-x-6 gap-y-2">
          {steps.map((s, i) => (
            <li
              key={s.id}
              className={`flex items-center gap-2 text-sm ${
                i === idx
                  ? "font-semibold text-primary"
                  : i < idx
                    ? "text-foreground"
                    : "text-muted-foreground"
              }`}
            >
              {i < idx ? (
                <CheckCircle2 className="size-4 text-success" />
              ) : (
                <span className="flex size-5 items-center justify-center rounded-full border text-xs">
                  {i + 1}
                </span>
              )}
              {s.label}
            </li>
          ))}
        </ol>
      </section>

      {Object.keys(errors).length > 0 && (
        <Alert variant="destructive">
          <AlertTitle>Please fix the highlighted fields</AlertTitle>
          <AlertDescription>
            {Object.keys(errors).length} field(s) need your attention.
          </AlertDescription>
        </Alert>
      )}

      <Card>
        <CardContent className="space-y-6 p-8">
          {step.id === "personal" && (
            <div className="grid gap-5 sm:grid-cols-2">
              <FieldBox label="First name" id="fn" error={errors.firstName}>
                <Input id="fn" value={p.firstName} onChange={(ev) => setP("firstName", ev.target.value)} />
              </FieldBox>
              <FieldBox label="Last name" id="ln" error={errors.lastName}>
                <Input id="ln" value={p.lastName} onChange={(ev) => setP("lastName", ev.target.value)} />
              </FieldBox>
              <FieldBox label="Preferred name" id="pn">
                <Input id="pn" value={p.preferredName} onChange={(ev) => setP("preferredName", ev.target.value)} />
              </FieldBox>
              <FieldBox label="Email" id="em" error={errors.email}>
                <Input id="em" type="email" value={p.email} onChange={(ev) => setP("email", ev.target.value)} />
              </FieldBox>
              <FieldBox label="Phone" id="ph">
                <Input id="ph" value={p.phone} onChange={(ev) => setP("phone", ev.target.value)} />
              </FieldBox>
              <FieldBox label="Date of birth" id="dob" error={errors.dateOfBirth}>
                <Input id="dob" type="date" value={p.dateOfBirth} onChange={(ev) => setP("dateOfBirth", ev.target.value)} />
              </FieldBox>
              <div className="sm:col-span-2">
                <FieldBox label="Address" id="ad">
                  <Input id="ad" value={p.address} onChange={(ev) => setP("address", ev.target.value)} />
                </FieldBox>
              </div>
              <FieldBox label="City" id="ci">
                <Input id="ci" value={p.city} onChange={(ev) => setP("city", ev.target.value)} />
              </FieldBox>
              <FieldBox label="Postal code" id="pc">
                <Input id="pc" value={p.postalCode} onChange={(ev) => setP("postalCode", ev.target.value)} />
              </FieldBox>
              <FieldBox label="Country" error={errors.country}>
                <Select value={p.country} onValueChange={(v) => setP("country", v)}>
                  <SelectTrigger><SelectValue placeholder="Select country" /></SelectTrigger>
                  <SelectContent>
                    {countries.map((c) => (<SelectItem key={c} value={c}>{c}</SelectItem>))}
                  </SelectContent>
                </Select>
              </FieldBox>
              <div className="sm:col-span-2"><Separator /></div>
              <FieldBox label="Emergency contact name" id="ecn" error={errors.emergencyContactName}>
                <Input id="ecn" value={p.emergencyContactName} onChange={(ev) => setP("emergencyContactName", ev.target.value)} />
              </FieldBox>
              <FieldBox label="Emergency contact phone" id="ecp">
                <Input id="ecp" value={p.emergencyContactPhone} onChange={(ev) => setP("emergencyContactPhone", ev.target.value)} />
              </FieldBox>
            </div>
          )}

          {step.id === "role" && (
            <div className="grid gap-5 sm:grid-cols-2">
              <div className="sm:col-span-2">
                <FieldBox label="Job title" id="jt" error={errors.jobTitle}>
                  <Input id="jt" value={r.jobTitle} onChange={(ev) => setR("jobTitle", ev.target.value)} />
                </FieldBox>
              </div>
              <FieldBox label="Department" error={errors.departmentId}>
                <Select
                  value={r.departmentId}
                  onValueChange={(v) =>
                    setDraft({ ...draft, role: { ...r, departmentId: v, team: "", managerId: "" } })
                  }
                >
                  <SelectTrigger><SelectValue placeholder="Select department" /></SelectTrigger>
                  <SelectContent>
                    {departments.map((d) => (<SelectItem key={d.id} value={d.id}>{d.name}</SelectItem>))}
                  </SelectContent>
                </Select>
              </FieldBox>
              <FieldBox label="Team" error={errors.team}>
                <Select value={r.team} onValueChange={(v) => setR("team", v)}>
                  <SelectTrigger><SelectValue placeholder={dept ? "Select team" : "Pick a department first"} /></SelectTrigger>
                  <SelectContent>
                    {teams.map((t) => (<SelectItem key={t} value={t}>{t}</SelectItem>))}
                  </SelectContent>
                </Select>
              </FieldBox>
              <FieldBox label="Manager" error={errors.managerId}>
                <Select value={r.managerId} onValueChange={(v) => setR("managerId", v)}>
                  <SelectTrigger><SelectValue placeholder="Select manager" /></SelectTrigger>
                  <SelectContent>
                    {deptManagers.map((m) => (<SelectItem key={m.id} value={m.id}>{m.name} · {m.title}</SelectItem>))}
                  </SelectContent>
                </Select>
              </FieldBox>
              <FieldBox label="Employment type" error={errors.employmentType}>
                <Select value={r.employmentType} onValueChange={(v) => setR("employmentType", v)}>
                  <SelectTrigger><SelectValue placeholder="Select type" /></SelectTrigger>
                  <SelectContent>
                    {employmentTypes.map((t) => (<SelectItem key={t.id} value={t.id}>{t.label}</SelectItem>))}
                  </SelectContent>
                </Select>
              </FieldBox>
              <FieldBox label="Start date" id="sd" error={errors.startDate}>
                <Input id="sd" type="date" value={r.startDate} onChange={(ev) => setR("startDate", ev.target.value)} />
              </FieldBox>
              <FieldBox label="Office location" error={errors.location}>
                <Select value={r.location} onValueChange={(v) => setR("location", v)}>
                  <SelectTrigger><SelectValue placeholder="Select location" /></SelectTrigger>
                  <SelectContent>
                    {officeLocations.map((l) => (<SelectItem key={l} value={l}>{l}</SelectItem>))}
                  </SelectContent>
                </Select>
              </FieldBox>
            </div>
          )}

          {step.id === "equipment" && (
            <div className="space-y-8">
              <div className="space-y-3">
                <h3 className="font-medium">Laptop</h3>
                {optionList(laptops, e.laptopId, (v) => setE({ laptopId: v }), errors.laptopId)}
              </div>
              <div className="space-y-3">
                <h3 className="font-medium">Monitor</h3>
                {optionList(monitors, e.monitorId, (v) => setE({ monitorId: v }), errors.monitorId)}
              </div>
              <div className="space-y-3">
                <h3 className="font-medium">Peripherals</h3>
                <div className="grid gap-3 sm:grid-cols-2">
                  {peripherals.map((o) => (
                    <label key={o.id} htmlFor={`pe-${o.id}`} className="flex cursor-pointer items-center gap-3 rounded-lg border p-4">
                      <Checkbox
                        id={`pe-${o.id}`}
                        checked={e.peripheralIds.includes(o.id)}
                        onCheckedChange={(c) =>
                          setE({
                            peripheralIds: c === true
                              ? [...e.peripheralIds, o.id]
                              : e.peripheralIds.filter((x) => x !== o.id),
                          })
                        }
                      />
                      <span className="flex-1 text-sm font-medium">{o.name}</span>
                      <span className="text-sm tabular-nums">{money(o.price)}</span>
                    </label>
                  ))}
                </div>
              </div>
              <FieldBox label="Shipping address" id="sa" error={errors.shippingAddress}>
                <Textarea id="sa" rows={3} value={e.shippingAddress} onChange={(ev) => setE({ shippingAddress: ev.target.value })} />
              </FieldBox>
              <FieldBox label="Notes" id="nt">
                <Textarea id="nt" rows={2} value={e.notes} onChange={(ev) => setE({ notes: ev.target.value })} />
              </FieldBox>
            </div>
          )}

          {step.id === "benefits" && (
            <div className="space-y-8">
              {planPicker("health", "Health", b.healthPlanId, "healthPlanId", errors.healthPlanId)}
              {planPicker("dental", "Dental", b.dentalPlanId, "dentalPlanId")}
              {planPicker("vision", "Vision", b.visionPlanId, "visionPlanId")}
              <div className="space-y-3">
                <div className="flex justify-between">
                  <h3 className="font-medium">401(k) contribution</h3>
                  <span className="font-semibold tabular-nums">{b.retirementPercent}%</span>
                </div>
                <Slider
                  value={[b.retirementPercent]}
                  min={0}
                  max={20}
                  step={1}
                  onValueChange={(v) => setB({ retirementPercent: v[0] ?? 0 })}
                />
                <p className="text-xs text-muted-foreground">
                  Employer matches up to {retirementMatchCapPercent}%.
                </p>
              </div>
              <div className="space-y-3">
                <h3 className="font-medium">Wellness</h3>
                {plansBy("wellness").map((pl) => (
                  <div key={pl.id} className="flex items-center justify-between rounded-lg border p-4">
                    <div>
                      <Label htmlFor={`w-${pl.id}`}>{pl.name}</Label>
                      <p className="text-xs text-muted-foreground">{pl.description}</p>
                    </div>
                    <Switch
                      id={`w-${pl.id}`}
                      checked={b.wellnessIds.includes(pl.id)}
                      onCheckedChange={(c) =>
                        setB({
                          wellnessIds: c
                            ? [...b.wellnessIds, pl.id]
                            : b.wellnessIds.filter((x) => x !== pl.id),
                        })
                      }
                    />
                  </div>
                ))}
              </div>
            </div>
          )}

          {step.id === "review" && (
            <div className="space-y-6">
              <div>
                <CardTitle className="mb-2">Personal</CardTitle>
                {row("Name", `${p.firstName} ${p.lastName}`)}
                {row("Email", p.email)}
                {row("Country", p.country)}
                {row("Emergency contact", p.emergencyContactName)}
              </div>
              <Separator />
              <div>
                <CardTitle className="mb-2">Role</CardTitle>
                {row("Title", r.jobTitle)}
                {row("Department", dept?.name ?? "")}
                {row("Team", r.team)}
                {row("Manager", find(managers, r.managerId)?.name ?? "")}
                {row("Start date", r.startDate)}
                {row("Location", r.location)}
              </div>
              <Separator />
              <div>
                <CardTitle className="mb-2">Equipment</CardTitle>
                {row("Laptop", find(laptops, e.laptopId)?.name ?? "")}
                {row("Monitor", find(monitors, e.monitorId)?.name ?? "")}
                {row("Peripherals", `${e.peripheralIds.length} selected`)}
                {row("Total value", money(equipCost))}
              </div>
              <Separator />
              <div>
                <CardTitle className="mb-2">Benefits</CardTitle>
                {row("Health", find(benefitPlans, b.healthPlanId)?.name ?? "")}
                {row("Dental", find(benefitPlans, b.dentalPlanId)?.name ?? "")}
                {row("Vision", find(benefitPlans, b.visionPlanId)?.name ?? "")}
                {row("401(k)", `${b.retirementPercent}%`)}
                {row("Your monthly cost", money(benefitCost))}
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      <div className="flex items-center justify-between">
        <Button variant="ghost" onClick={back} disabled={idx === 0}>
          <ArrowLeft /> Back
        </Button>
        <Button size="lg" onClick={next}>
          {step.id === "review" ? (
            <>
              Submit <Check />
            </>
          ) : (
            <>
              Continue <ArrowRight />
            </>
          )}
        </Button>
      </div>
    </div>
  );
}

// keep Card helpers referenced for consistent theming
void CardHeader;
void CardDescription;

form-c.final:
import {
  Alert,
  AlertDescription,
  AlertTitle,
  Badge,
  Button,
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
  Checkbox,
  Input,
  Label,
  Progress,
  RadioGroup,
  RadioGroupItem,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Separator,
  Slider,
  Switch,
  Textarea,
} from "@databricks/appkit-ui/react";
import {
  AlertCircle,
  Check,
  CheckCircle2,
  ChevronLeft,
  ChevronRight,
  Send,
} from "lucide-react";
import { useState } from "react";

import {
  benefitPlans,
  countries,
  departments,
  emptyDraft,
  employmentTypes,
  laptops,
  managers,
  monitors,
  officeLocations,
  peripherals,
  retirementMatchCapPercent,
  sampleDraft,
  steps,
} from "../mock";
import type { OnboardingDraft, StepId, ValidationErrors } from "../mock";

const money = (n: number) => `$${n.toLocaleString()}`;

function validate(id: StepId, d: OnboardingDraft): ValidationErrors {
  const e: ValidationErrors = {};
  if (id === "personal") {
    const p = d.personal;
    if (!p.firstName.trim()) e.firstName = "First name is required";
    if (!p.lastName.trim()) e.lastName = "Last name is required";
    if (!/^\S+@\S+\.\S+$/.test(p.email)) e.email = "Enter a valid email";
    if (!p.phone.trim()) e.phone = "Phone is required";
    if (!p.dateOfBirth) e.dateOfBirth = "Date of birth is required";
    if (!p.address.trim()) e.address = "Address is required";
    if (!p.city.trim()) e.city = "City is required";
    if (!p.country) e.country = "Select a country";
    if (!p.postalCode.trim()) e.postalCode = "Postal code is required";
    if (!p.emergencyContactName.trim())
      e.emergencyContactName = "Emergency contact is required";
    if (!p.emergencyContactPhone.trim())
      e.emergencyContactPhone = "Emergency phone is required";
  } else if (id === "role") {
    const r = d.role;
    if (!r.jobTitle.trim()) e.jobTitle = "Job title is required";
    if (!r.departmentId) e.departmentId = "Select a department";
    if (!r.team) e.team = "Select a team";
    if (!r.managerId) e.managerId = "Select a manager";
    if (!r.employmentType) e.employmentType = "Select employment type";
    if (!r.startDate) e.startDate = "Start date is required";
    if (!r.location) e.location = "Select a location";
  } else if (id === "equipment") {
    const q = d.equipment;
    if (!q.laptopId) e.laptopId = "Choose a laptop";
    if (!q.monitorId) e.monitorId = "Choose a monitor option";
    if (!q.shippingAddress.trim())
      e.shippingAddress = "Shipping address is required";
  } else if (id === "benefits") {
    const b = d.benefits;
    if (!b.healthPlanId) e.healthPlanId = "Choose a health plan";
    if (!b.dentalPlanId) e.dentalPlanId = "Choose a dental plan";
    if (!b.visionPlanId) e.visionPlanId = "Choose a vision plan";
  }
  return e;
}

function FieldBox({
  label,
  error,
  children,
}: {
  label: string;
  error?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="space-y-1">
      <Label className="text-xs text-muted-foreground">{label}</Label>
      {children}
      {error && <p className="text-xs text-destructive">{error}</p>}
    </div>
  );
}

export default function Onboarding() {
  const [draft, setDraft] = useState<OnboardingDraft>(emptyDraft);
  const [idx, setIdx] = useState(0);
  const [errors, setErrors] = useState<ValidationErrors>({});
  const [done, setDone] = useState<Record<string, boolean>>({});
  const [submitted, setSubmitted] = useState(false);
  const [confirm, setConfirm] = useState(false);

  const step = steps[idx];
  const { personal: p, role: r, equipment: q, benefits: b } = draft;

  const setP = (k: keyof typeof p, v: string) =>
    setDraft({ ...draft, personal: { ...p, [k]: v } });
  const setR = (k: keyof typeof r, v: string) =>
    setDraft({
      ...draft,
      role: { ...r, [k]: v, ...(k === "departmentId" ? { team: "", managerId: "" } : {}) },
    });
  const setQ = (patch: Partial<typeof q>) =>
    setDraft({ ...draft, equipment: { ...q, ...patch } });
  const setB = (patch: Partial<typeof b>) =>
    setDraft({ ...draft, benefits: { ...b, ...patch } });

  const goto = (i: number) => {
    setErrors({});
    setIdx(i);
  };
  const next = () => {
    const e = validate(step.id, draft);
    setErrors(e);
    if (Object.keys(e).length === 0) {
      setDone({ ...done, [step.id]: true });
      setIdx(idx + 1);
    }
  };
  const submit = () => {
    for (const s of steps) {
      const e = validate(s.id, draft);
      if (Object.keys(e).length) {
        setErrors(e);
        setIdx(steps.findIndex((x) => x.id === s.id));
        return;
      }
    }
    setSubmitted(true);
  };

  const dept = departments.find((d) => d.id === r.departmentId);
  const deptManagers = managers.filter((m) => m.departmentId === r.departmentId);
  const allEquip = [...laptops, ...monitors, ...peripherals];
  const equipItems = allEquip.filter(
    (x) =>
      x.id === q.laptopId || x.id === q.monitorId || q.peripheralIds.includes(x.id),
  );
  const equipTotal = equipItems.reduce((s, x) => s + x.price, 0);
  const chosenPlans = benefitPlans.filter(
    (x) =>
      [b.healthPlanId, b.dentalPlanId, b.visionPlanId].includes(x.id) ||
      b.wellnessIds.includes(x.id),
  );
  const monthly = chosenPlans.reduce(
    (s, x) => s + Math.max(0, x.monthlyCost - x.employerContribution),
    0,
  );
  const pct = Math.round((Object.values(done).filter(Boolean).length / steps.length) * 100);

  const planGroup = (
    cat: string,
    key: "healthPlanId" | "dentalPlanId" | "visionPlanId",
    title: string,
  ) => (
    <div className="space-y-2">
      <div className="text-sm font-medium">{title}</div>
      <RadioGroup value={b[key]} onValueChange={(v) => setB({ [key]: v })}>
        {benefitPlans
          .filter((x) => x.category === cat)
          .map((x) => (
            <label
              key={x.id}
              htmlFor={`${key}-${x.id}`}
              className="flex cursor-pointer items-start gap-3 rounded-md border p-2.5 text-sm"
            >
              <RadioGroupItem value={x.id} id={`${key}-${x.id}`} />
              <div className="flex-1">
                <div className="font-medium">{x.name}</div>
                <div className="text-xs text-muted-foreground">{x.description}</div>
              </div>
              <div className="text-right text-xs tabular-nums">
                <div>{money(x.monthlyCost)}/mo</div>
                <div className="text-success">
                  -{money(x.employerContribution)} employer
                </div>
              </div>
            </label>
          ))}
      </RadioGroup>
      {errors[key] && <p className="text-xs text-destructive">{errors[key]}</p>}
    </div>
  );

  if (submitted) {
    return (
      <div className="mx-auto max-w-xl p-6">
        <Card>
          <CardHeader className="items-center text-center">
            <CheckCircle2 className="size-10 text-success" />
            <CardTitle>Onboarding submitted</CardTitle>
            <CardDescription>
              {p.firstName} {p.lastName} starts {r.startDate}. IT and HR have been
              notified.
            </CardDescription>
          </CardHeader>
          <CardFooter className="justify-center">
            <Button
              variant="outline"
              onClick={() => {
                setDraft(emptyDraft);
                setDone({});
                setIdx(0);
                setConfirm(false);
                setSubmitted(false);
              }}
            >
              Start another
            </Button>
          </CardFooter>
        </Card>
      </div>
    );
  }

  const textField = (label: string, k: keyof typeof p, type = "text") => (
    <FieldBox label={label} error={errors[k]}>
      <Input type={type} value={p[k]} onChange={(e) => setP(k, e.target.value)} />
    </FieldBox>
  );

  const reviewRow = (k: string, v: string) => (
    <div className="flex justify-between gap-4 py-1 text-sm">
      <span className="text-muted-foreground">{k}</span>
      <span className="text-right font-medium">{v || "—"}</span>
    </div>
  );

  return (
    <div className="mx-auto max-w-6xl p-4">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-xl font-semibold tracking-tight">New hire onboarding</h1>
          <p className="text-xs text-muted-foreground">
            Step {idx + 1} of {steps.length} · {pct}% complete
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="ghost" size="sm" onClick={() => setDraft(sampleDraft)}>
            Fill sample
          </Button>
          <div className="w-40">
            <Progress value={pct} />
          </div>
        </div>
      </div>

      <div className="grid gap-4 md:grid-cols-[220px_1fr]">
        <nav className="space-y-1">
          {steps.map((s, i) => {
            const active = i === idx;
            return (
              <button
                key={s.id}
                type="button"
                onClick={() => (i <= idx || done[steps[i - 1]?.id] ? goto(i) : undefined)}
                className={`flex w-full items-start gap-2 rounded-md border p-2 text-left text-sm ${
                  active ? "border-primary bg-accent" : "border-transparent hover:bg-muted"
                }`}
              >
                <span
                  className={`mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-full text-xs ${
                    done[s.id]
                      ? "bg-success text-primary-foreground"
                      : active
                        ? "bg-primary text-primary-foreground"
                        : "bg-muted text-muted-foreground"
                  }`}
                >
                  {done[s.id] ? <Check className="size-3" /> : i + 1}
                </span>
                <span>
                  <span className="block font-medium">{s.label}</span>
                  <span className="block text-xs text-muted-foreground">
                    {s.description}
                  </span>
                </span>
              </button>
            );
          })}
        </nav>

        <Card>
          <CardHeader>
            <CardTitle>{step.label}</CardTitle>
            <CardDescription>{step.description}</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {Object.keys(errors).length > 0 && (
              <Alert variant="destructive">
                <AlertCircle />
                <AlertTitle>Fix {Object.keys(errors).length} issue(s) to continue</AlertTitle>
                <AlertDescription>Highlighted fields need attention.</AlertDescription>
              </Alert>
            )}

            {step.id === "personal" && (
              <div className="grid gap-3 sm:grid-cols-2">
                {textField("First name", "firstName")}
                {textField("Last name", "lastName")}
                {textField("Preferred name", "preferredName")}
                {textField("Email", "email", "email")}
                {textField("Phone", "phone")}
                {textField("Date of birth", "dateOfBirth", "date")}
                <div className="sm:col-span-2">{textField("Address", "address")}</div>
                {textField("City", "city")}
                <FieldBox label="Country" error={errors.country}>
                  <Select value={p.country} onValueChange={(v) => setP("country", v)}>
                    <SelectTrigger>
                      <SelectValue placeholder="Select country" />
                    </SelectTrigger>
                    <SelectContent>
                      {countries.map((c) => (
                        <SelectItem key={c} value={c}>
                          {c}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </FieldBox>
                {textField("Postal code", "postalCode")}
                <div />
                {textField("Emergency contact", "emergencyContactName")}
                {textField("Emergency phone", "emergencyContactPhone")}
              </div>
            )}

            {step.id === "role" && (
              <div className="grid gap-3 sm:grid-cols-2">
                <FieldBox label="Job title" error={errors.jobTitle}>
                  <Input value={r.jobTitle} onChange={(e) => setR("jobTitle", e.target.value)} />
                </FieldBox>
                <FieldBox label="Employment type" error={errors.employmentType}>
                  <Select value={r.employmentType} onValueChange={(v) => setR("employmentType", v)}>
                    <SelectTrigger>
                      <SelectValue placeholder="Select type" />
                    </SelectTrigger>
                    <SelectContent>
                      {employmentTypes.map((t) => (
                        <SelectItem key={t.id} value={t.id}>
                          {t.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </FieldBox>
                <FieldBox label="Department" error={errors.departmentId}>
                  <Select value={r.departmentId} onValueChange={(v) => setR("departmentId", v)}>
                    <SelectTrigger>
                      <SelectValue placeholder="Select department" />
                    </SelectTrigger>
                    <SelectContent>
                      {departments.map((d) => (
                        <SelectItem key={d.id} value={d.id}>
                          {d.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </FieldBox>
                <FieldBox label="Team" error={errors.team}>
                  <Select value={r.team} onValueChange={(v) => setR("team", v)}>
                    <SelectTrigger>
                      <SelectValue placeholder={dept ? "Select team" : "Pick department first"} />
                    </SelectTrigger>
                    <SelectContent>
                      {(dept?.teams ?? []).map((t) => (
                        <SelectItem key={t} value={t}>
                          {t}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </FieldBox>
                <FieldBox label="Manager" error={errors.managerId}>
                  <Select value={r.managerId} onValueChange={(v) => setR("managerId", v)}>
                    <SelectTrigger>
                      <SelectValue placeholder={dept ? "Select manager" : "Pick department first"} />
                    </SelectTrigger>
                    <SelectContent>
                      {deptManagers.map((m) => (
                        <SelectItem key={m.id} value={m.id}>
                          {m.name} · {m.title}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </FieldBox>
                <FieldBox label="Start date" error={errors.startDate}>
                  <Input type="date" value={r.startDate} onChange={(e) => setR("startDate", e.target.value)} />
                </FieldBox>
                <FieldBox label="Office location" error={errors.location}>
                  <Select value={r.location} onValueChange={(v) => setR("location", v)}>
                    <SelectTrigger>
                      <SelectValue placeholder="Select location" />
                    </SelectTrigger>
                    <SelectContent>
                      {officeLocations.map((l) => (
                        <SelectItem key={l} value={l}>
                          {l}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </FieldBox>
              </div>
            )}

            {step.id === "equipment" && (
              <div className="space-y-4">
                {(
                  [
                    ["Laptop", laptops, "laptopId"],
                    ["Monitor", monitors, "monitorId"],
                  ] as const
                ).map(([title, list, key]) => (
                  <div key={key} className="space-y-2">
                    <div className="text-sm font-medium">{title}</div>
                    <RadioGroup value={q[key]} onValueChange={(v) => setQ({ [key]: v })}>
                      {list.map((o) => (
                        <label
                          key={o.id}
                          htmlFor={`${key}-${o.id}`}
                          className="flex cursor-pointer items-center gap-3 rounded-md border p-2.5 text-sm"
                        >
                          <RadioGroupItem value={o.id} id={`${key}-${o.id}`} />
                          <div className="flex-1">
                            <div className="font-medium">{o.name}</div>
                            <div className="text-xs text-muted-foreground">{o.description}</div>
                          </div>
                          <span className="tabular-nums">{money(o.price)}</span>
                        </label>
                      ))}
                    </RadioGroup>
                    {errors[key] && <p className="text-xs text-destructive">{errors[key]}</p>}
                  </div>
                ))}
                <div className="space-y-2">
                  <div className="text-sm font-medium">Peripherals & accessories</div>
                  <div className="grid gap-2 sm:grid-cols-2">
                    {peripherals.map((o) => (
                      <label
                        key={o.id}
                        htmlFor={`per-${o.id}`}
                        className="flex cursor-pointer items-center gap-3 rounded-md border p-2.5 text-sm"
                      >
                        <Checkbox
                          id={`per-${o.id}`}
                          checked={q.peripheralIds.includes(o.id)}
                          onCheckedChange={(c) =>
                            setQ({
                              peripheralIds: c === true
                                ? [...q.peripheralIds, o.id]
                                : q.peripheralIds.filter((x) => x !== o.id),
                            })
                          }
                        />
                        <span className="flex-1">{o.name}</span>
                        <span className="tabular-nums text-muted-foreground">{money(o.price)}</span>
                      </label>
                    ))}
                  </div>
                </div>
                <FieldBox label="Shipping address" error={errors.shippingAddress}>
                  <Input value={q.shippingAddress} onChange={(e) => setQ({ shippingAddress: e.target.value })} />
                </FieldBox>
                <FieldBox label="Notes">
                  <Textarea rows={2} value={q.notes} onChange={(e) => setQ({ notes: e.target.value })} />
                </FieldBox>
                <div className="text-right text-sm text-muted-foreground">
                  Equipment total: <span className="font-semibold text-foreground">{money(equipTotal)}</span>
                </div>
              </div>
            )}

            {step.id === "benefits" && (
              <div className="space-y-4">
                {planGroup("health", "healthPlanId", "Health")}
                {planGroup("dental", "dentalPlanId", "Dental")}
                {planGroup("vision", "visionPlanId", "Vision")}
                <Separator />
                <div className="space-y-2">
                  <div className="flex justify-between text-sm">
                    <span className="font-medium">Retirement contribution</span>
                    <span className="tabular-nums">{b.retirementPercent}%</span>
                  </div>
                  <Slider
                    value={[b.retirementPercent]}
                    min={0}
                    max={20}
                    step={1}
                    onValueChange={(v) => setB({ retirementPercent: v[0] ?? 0 })}
                  />
                  <p className="text-xs text-muted-foreground">
                    Employer matches up to {retirementMatchCapPercent}% (matched:{" "}
                    {Math.min(b.retirementPercent, retirementMatchCapPercent)}%).
                  </p>
                </div>
                <div className="space-y-2">
                  <div className="text-sm font-medium">Wellness add-ons</div>
                  {benefitPlans
                    .filter((x) => x.category === "wellness")
                    .map((x) => (
                      <div key={x.id} className="flex items-center justify-between rounded-md border p-2.5 text-sm">
                        <div>
                          <div className="font-medium">{x.name}</div>
                          <div className="text-xs text-muted-foreground">{x.description}</div>
                        </div>
                        <div className="flex items-center gap-3">
                          <span className="text-xs tabular-nums">{money(x.monthlyCost)}/mo</span>
                          <Switch
                            checked={b.wellnessIds.includes(x.id)}
                            onCheckedChange={(c) =>
                              setB({
                                wellnessIds: c
                                  ? [...b.wellnessIds, x.id]
                                  : b.wellnessIds.filter((w) => w !== x.id),
                              })
                            }
                          />
                        </div>
                      </div>
                    ))}
                </div>
                <div className="text-right text-sm text-muted-foreground">
                  Your monthly cost: <span className="font-semibold text-foreground">{money(monthly)}</span>
                </div>
              </div>
            )}

            {step.id === "review" && (
              <div className="grid gap-4 md:grid-cols-2">
                {[
                  {
                    t: "Personal",
                    i: 0,
                    rows: [
                      ["Name", `${p.firstName} ${p.lastName}`],
                      ["Email", p.email],
                      ["Phone", p.phone],
                      ["Location", `${p.city}, ${p.country}`],
                      ["Emergency", p.emergencyContactName],
                    ],
                  },
                  {
                    t: "Role & team",
                    i: 1,
                    rows: [
                      ["Title", r.jobTitle],
                      ["Department", dept?.name ?? ""],
                      ["Team", r.team],
                      ["Manager", managers.find((m) => m.id === r.managerId)?.name ?? ""],
                      ["Start", r.startDate],
                    ],
                  },
                  {
                    t: "Equipment",
                    i: 2,
                    rows: [
                      ...equipItems.map((x) => [x.name, money(x.price)]),
                      ["Total", money(equipTotal)],
                    ],
                  },
                  {
                    t: "Benefits",
                    i: 3,
                    rows: [
                      ...chosenPlans.map((x) => [x.name, `${money(Math.max(0, x.monthlyCost - x.employerContribution))}/mo`]),
                      ["401(k)", `${b.retirementPercent}%`],
                    ],
                  },
                ].map((sec) => (
                  <div key={sec.t} className="rounded-md border p-3">
                    <div className="mb-1 flex items-center justify-between">
                      <span className="text-sm font-semibold">{sec.t}</span>
                      <Button variant="link" size="sm" onClick={() => goto(sec.i)}>
                        Edit
                      </Button>
                    </div>
                    {sec.rows.map(([k, v]) => (
                      <div key={k + v}>{reviewRow(k as string, v as string)}</div>
                    ))}
                  </div>
                ))}
                <label htmlFor="confirm" className="flex items-center gap-2 text-sm md:col-span-2">
                  <Checkbox id="confirm" checked={confirm} onCheckedChange={(c) => setConfirm(c === true)} />
                  I confirm the information above is accurate.
                </label>
              </div>
            )}
          </CardContent>
          <CardFooter className="justify-between">
            <Button variant="outline" size="sm" disabled={idx === 0} onClick={() => goto(idx - 1)}>
              <ChevronLeft /> Back
            </Button>
            <div className="flex items-center gap-2">
              <Badge variant="secondary">{step.label}</Badge>
              {step.id === "review" ? (
                <Button size="sm" disabled={!confirm} onClick={submit}>
                  <Send /> Submit
                </Button>
              ) : (
                <Button size="sm" onClick={next}>
                  Next <ChevronRight />
                </Button>
              )}
            </div>
          </CardFooter>
        </Card>
      </div>
    </div>
  );
}
